请对以下 case 进行三维加权评分。

=== case_id ===
Case-07-sports-event-121

=== 用户原始指令 (query.txt) ===
整张比赛图当主体,点能进系统操作,红色危险提示

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "整张比赛图当主体,点能进系统操作,红色危险提示",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.calendar",
        "abilityName": "com.huawei.calendar.MainAbility",
        "uri": "calendar://event/sports-121"
      }
    }
  ],
  "dataModel": {
    "value": {
      "match": {
        "title": "申花 vs 海港",
        "time": "今晚 19:35 开赛",
        "alert": "危险赛点",
        "actionText": "进系统操作",
        "image": "assets/sports-match-hero.png"
      }
    }
  },
  "assetCandidates": [
    {
      "assetRef": "match_hero",
      "src": "assets/sports-match-hero.png",
      "use": "sports match hero image",
      "description": "整张比赛图素材，用作赛事提醒卡片主体背景，突出比赛现场氛围与赛事对象。",
      "bindTo": "/match/image"
    }
  ]
}

